const ft=r=>mn(pt(r,r.pts[0]));
function mt(r){const f=$('f').value,d=$('df').value;return Math.min(99,60+(f!==''&&r.pts.some(p=>pMt(p,+f))?15:0)+(d!==''&&dMt(r.dr,+d)?15:0)+(isVf(r)?5:0)+(r.left>1?4:0))}
function isVf(r){if(r.demo||VFD[r.driver])return true;const v=RATINGS[r.driver+'_vf'];return v&&v.every(Boolean)}
function sortR(L){if(so==='f')L=L.filter(r=>fv(r.id));L=[...L].sort((a,b)=>so==='m'?mt(b)-mt(a):so==='p'?a.price-b.price:so==='s'?b.left-a.left:ft(a)-ft(b));BD={};if(L.length){const c=[...L].sort((a,b)=>a.price-b.price)[0].id,e=[...L].sort((a,b)=>ft(a)-ft(b))[0].id;L.forEach(r=>{BD[r.id]=[];if(r.id===e)BD[r.id].push('الأقرب ميعاد');if(r.id===c)BD[r.id].push('الأرخص')})}
$('sr').innerHTML=SO.map(x=>`<button aria-pressed="${so===x[0]}" onclick="so='${x[0]}';render()">${x[1]}</button>`).join('');return L}
function card(r,extra){const c=R[r.r].c,f=$('f').value,b=[...(BD[r.id]||[]),...(r.w?['للسيدات']:[]),...(r.left===1?['آخر مقعد']:[]),...(isVf(r)?['موثّق ✓']:[]),...(r.vb||[]).slice(0,3).map(i=>VB[i])];
return `<article class="card rc" style="border-inline-start:5px solid ${c}" onclick="hl(${r.r});det(${r.id})"><div class="row"><div class="row" style="justify-content:flex-start;gap:10px"><span class="av sm" style="background:${c}">${esc(r.who).slice(0,1)}</span><div><b>${esc(r.who)}</b> ${RT_SUM[r.driver]?`<span class="mu" style="color:#F59E0B">★ ${RT_SUM[r.driver].avg} (${RT_SUM[r.driver].count})</span>`:''}<div class="mu">${esc(r.car)} · ${esc(r.col)}</div></div></div><div><span class="pr" style="font-size:24px">${r.price}</span> <span class="mu">جنيه</span><div class="mu">توافق ${mt(r)}%</div></div></div>${b.length?`<div class="bd">${b.map(x=>`<span class="${x==='للسيدات'?'w2':''}">${x}</span>`).join('')}</div>`:''}<div class="pills">${r.pts.map(i=>`<span class="pill ${f!==''&&pMt(i,+f)?'on':''}"><b>${pt(r,i)}</b>${PTS[i]}</span>`).join('')}</div><div class="mu">${R[r.r].n} · النزول: ${DROP[r.dr||0]}${r.ar?' · وصول تقريباً '+r.ar:''}</div>${r.days&&r.days.length?`<div class="mu">أيام: ${dayStr(r.days)}</div>`:''}<div class="row"><span class="seats" role="img" aria-label="متبقي ${r.left} من ${r.seats}">${Array.from({length:r.seats},(_,i)=>`<svg class="${i<r.seats-r.left?'e':''}"><use href="#pe"/></svg>`).join('')}</span><div class="pl">${esc(r.pl)}</div></div><div class="row" style="gap:8px"><button class="btn g" style="min-height:40px;flex:1" onclick="event.stopPropagation();wa(${r.id})">شارك على واتساب</button><button class="btn g" style="min-height:40px;width:48px;padding:0" aria-label="${fv(r.id)?'شيل من المفضلة':'ضيف للمفضلة'}" onclick="event.stopPropagation();fvt(${r.id})">${fv(r.id)?'★':'☆'}</button></div>${extra||''}</article>`}
function nearH(){const f=$('f').value;if(f==='')return '';const F=+f;if(F>=100||!PTS[F])return '';const n=RIDES.filter(r=>r.left>0&&!r.mine&&!r.pts.includes(F)&&r.pts.some(p=>Math.abs((OFF[p]||0)-(OFF[F]||0))<=8));return n.length?'<b style="display:block;margin:8px 0">مشاوير قريبة من '+PTS[F]+'</b>'+n.slice(0,3).map(r=>{const p=r.pts.reduce((a,b)=>Math.abs((OFF[b]||0)-(OFF[F]||0))<Math.abs((OFF[a]||0)-(OFF[F]||0))?b:a);return `<div class="card"><div class="row"><b>${PTS[p]}</b><span class="chip">بعيد حوالي ${Math.abs((OFF[p]||0)-(OFF[F]||0))} دقيقة على الطريق</span></div><div class="mu">${pt(r,p)} · ${R[r.r].n} · ${r.price} جنيه</div><button class="btn g" onclick="pks(1,'${p}')">اعرض من ${PTS[p]}</button></div>`}).join(''):''}
function render(){
  $('bal').textContent=PROFILE?PROFILE.balance:'…';
  const f=$('f').value,wf=$('wf').checked,df=$('df').value;
  const L=sortR(RIDES.filter(r=>(r.st==='open'||r.demo)&&!r.mine&&(f===''||r.pts.some(p=>pMt(p,+f)))&&(!wf||r.w)&&(df===''||dMt(r.dr,+df))));
  $('rides').innerHTML=L.length?L.map(r=>card(r,`<button class="btn" ${r.left?'':'disabled'} onclick="event.stopPropagation();openBk(${r.id})">${r.left?'احجز':'اكتمل'}</button>`)).join(''):'<div class="card" style="align-items:center;text-align:center"><svg viewBox="0 0 24 24" width="56" fill="var(--bd)"><path d="M12 22s7-6.2 7-12a7 7 0 10-14 0c0 5.8 7 12 7 12z"/></svg><b>مفيش مشاوير هنا دلوقتي</b><span class="mu">جرب تغير النقطة أو المكان، أو انشر مشوارك أنت.</span><button class="btn" onclick="rqf()">اطلب مشوار</button><button class="btn g" onclick="clr()">امسح الاختيارات</button></div>'+nearH();
  const act=MYBOOKS.filter(b=>['pending','countered','accepted','onboard'].includes(b.st));
  $('books').innerHTML=act.length?act.map((b,i)=>`<article class="card"><div class="row"><b><i class="dot" style="background:${R[b.rt].c}"></i>${PTS[b.p]} · ${b.t}</b><span class="pr">${b.price} جنيه</span></div><div class="mu">${esc(b.car)} · ${esc(b.col)} · ${esc(b.who)}</div><div class="pl">${esc(b.pl)}</div><div class="mu">${bSt(b)}${b.wk?' · اشتراك أسبوعي':''} · ${payDisp(payOf(b))}</div>${b.st==='countered'?`<div class="row"><button class="btn" onclick="rConfirm(${b.bid})">أقبل ${b.price} جنيه</button><button class="btn g" onclick="cancelBk(${b.bid})">رفض</button></div>`:`<button class="btn g" onclick="cancelBk(${b.bid})">إلغاء الحجز</button>`}</article>`).join(''):'<p class="mu">لسه ما حجزتش حاجة.</p>';
  $('mine').innerHTML=MYRIDES.length?MYRIDES.map(r=>card(r,paxH(r))).join(''):'<p class="mu">لسه ما نشرتش مشاوير.</p>';
  extra()}
function bSt(b){return {pending:'في انتظار رد السواق',countered:'السواق رد بسعر '+b.price,accepted:'اتأكد الحجز · كودك '+b.pin,onboard:'في الرحلة',done:'خلصت',cancelled:'ملغي',rejected:'مرفوض'}[b.st]||b.st}
function extra(){$('mapw').hidden=$('v1').hidden&&$('v2').hidden;renderTrip();renderHist();nxr();vfr();profR();vbr();bell();psr();pkt();drvRt();
$('stat').innerHTML=`<div class="card"><b>لوحة السواق</b><div class="row"><span class="mu">ركاب ركبوا معاك</span><b>${DST.pax||0}</b></div><div class="row"><span class="mu">عمولة اتدفعت</span><b>${DST.commission||0} جنيه</b></div><div class="row"><span class="mu">كاش استلمته</span><b class="pr">${DST.earned||0} جنيه</b></div></div>`+lowB()+lvh()}
let DST={};
async function refreshStats(){const{data}=await sb.rpc('driver_stats');if(data)DST=data}
function lowB(){return PROFILE&&PROFILE.balance<30?`<div class="card" style="border-color:var(--er)"><b>رصيدك قليل</b><span class="mu">لما الرصيد يقل عن العمولة مش هتقدر تسجّل ركاب. اشحن الأول.</span><button class="btn" onclick="wal()">اشحن دلوقتي</button></div>`:''}
function lvh(){const p=(DST.pax||0)*10,L=[['برونزي',0],['فضي',50],['ذهبي',150],['بلاتيني',400]];let i=0;L.forEach((x,k)=>{if(p>=x[1])i=k});const nx=L[i+1],pg=nx?(p-L[i][1])/(nx[1]-L[i][1]):1;return `<div class="card"><div class="row"><b>مستواك: ${L[i][0]}</b><span class="chip">${p} نقطة</span></div><div class="stp"><span class="${pg>0?'on':''}"></span><span class="${pg>.33?'on':''}"></span><span class="${pg>.66?'on':''}"></span><span class="${pg>=1?'on':''}"></span></div><span class="mu">${nx?'باقي '+(nx[1]-p)+' نقطة للمستوى '+nx[0]:'وصلت لأعلى مستوى'} · كل راكب بيركب معاك = 10 نقاط</span></div>`+gl()+rqd()}
function gl(){const g=S.goal||300,p=DST.earned||0;return `<div class="card"><div class="row"><b>هدفك النهارده</b><span class="chip">${p} / ${g} جنيه</span></div><div style="height:8px;border-radius:4px;background:var(--bd)"><div style="height:8px;border-radius:4px;background:var(--ac);width:${Math.min(100,100*p/g)}%;transition:width .6s"></div></div><input type="number" aria-label="هدفك اليومي بالجنيه" value="${g}" onchange="S.goal=+this.value||300;save();render()"></div>`}
