function openBk(id){const r=RIDES.find(x=>x.id===id);if(!r)return;
if(MYBOOKS.some(b=>b.rid===id&&['pending','countered','accepted','onboard'].includes(b.st)))return toast('انت حاجز في المشوار ده بالفعل.');
bk=id;off=r.price;hl(r.r);pm=S.payDef||'cash';wkf=false;const f=$('f').value;bp=f!==''?(r.pts.find(p=>pMt(p,+f))??null):null;
$('bk').innerHTML=`<div class="card" id="bkc"><div class="row"><b>احجز مقعد</b><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><span class="mu">${R[r.r].n} · النزول: ${DROP[r.dr||0]}</span><label>اختار نقطة الركوب</label><div>${r.pts.map(i=>`<button class="pp2" id="bp${i}" aria-pressed="false" onclick="pickP(${i})"><span><b>${PTS[i]}</b><br><span class="mu">السواق بيعدي الساعة ${pt(r,i)}</span></span><span class="tick"></span></button>`).join('')}</div><span class="mu" id="sum" role="status">اختار النقطة اللي هتركب منها.</span><label>عرضك للمقعد (جنيه)</label><div class="row"><button class="btn g" aria-label="قلل" onclick="stp(-5)">−</button><b class="pr" id="off">${off}</b><button class="btn g" aria-label="زوّد" onclick="stp(5)">+</button></div><span class="mu">السعر المعلن ${r.price} جنيه، كاش للسواق. تقدر تعرض أقل والسواق يقبل أو يرد بسعر.</span><label style="display:flex;align-items:center;gap:8px;font-weight:700"><input type="checkbox" id="wk" style="width:20px;min-height:20px" onchange="wkc()">اشتراك أسبوعي (5 أيام)</label><span class="mu" id="wks"></span><label>طريقة الدفع</label><div>${PAYM.map(x=>`<button class="pmo" data-m="${x[0]}" aria-pressed="${pm===x[0]}" onclick="pmSet('${x[0]}')"><span class="pmic">${uiIcon(x[3])}</span><span class="pmt"><b>${x[1]}</b><small>${x[2]}</small></span><span class="tick"></span></button>`).join('')}</div><span class="mu" id="pmn">${payNote()}</span><button class="btn" id="sbtn" onclick="payReview()" disabled>كمّل للتأكيد</button></div>`;if(bp!==null)pickP(bp)}
function pickP(i){bp=i;const r=RIDES.find(x=>x.id===bk);document.querySelectorAll('.pp2').forEach(b=>b.setAttribute('aria-pressed',b.id==='bp'+i?'true':'false'));$('sbtn').disabled=false;$('sum').textContent='هتركب من '+PTS[i]+' الساعة '+pt(r,i)+'. كون جاهز قبلها بـ 5 دقايق.'}
