function rqd(){const L=RQS;return `<div class="card"><b>طلبات ركاب (${L.length})</b><span class="mu">ركاب مستنيين مشوار على طريقك. اضغط وانشر مشوارك بسرعة.</span>${L.length?L.map(x=>`<div class="row"><div><b style="font-weight:400">${PTS[x.p]} ← ${DROP[x.d]}</b><div class="mu">${x.t} · ${esc(x.who||'راكب')}</div></div>${x.user_id===ME?'<span class="chip">طلبك</span>':`<button class="btn" style="min-height:36px" onclick="fillRq(${x.id})">عندي مشوار</button>`}</div>`).join(''):'<span class="mu">مفيش طلبات دلوقتي.</span>'}</div>`}
function fillRq(id){const x=RQS.find(y=>y.id===id);if(!x)return;tab(2);if($('v2').classList.contains('cl'))tg2();document.querySelectorAll('.pp').forEach(e=>e.checked=+e.value===x.p);$('dr').value=x.d;$('time').value=x.t.padStart(5,'0');man={};ttRender();ps=1;psr();toast('جهزنالك المشوار. اكتب بيانات عربيتك وكمّل.')}

// ---------- pickers / custom points ----------
function ord(){const k=i=>i>=100?[1,i]:[0,OFF[i]||0];return PTS.map((n,i)=>i).filter(i=>PTS[i]).sort((a,b)=>{const x=k(a),y=k(b);return x[0]-y[0]||x[1]-y[1]})}
const og=()=>[['الجيزة',i=>i<29||i>=111],['القاهرة',i=>i>=29&&i<111]].map(g=>`<optgroup label="${g[0]}">`+DROP.map((p,i)=>[p,i]).filter(x=>x[0]&&g[1](x[1])).map(x=>`<option value="${x[1]}">${x[0]}</option>`).join('')+'</optgroup>').join('');
function pkt(){const a=$('f').value,b=$('df').value,ch='<svg viewBox="0 0 24 24" width="16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 9l6 6 6-6"/></svg>';$('pk1').innerHTML='<span>'+(a===''?'كل النقاط':pl1(+a))+'</span>'+ch;$('pk2').innerHTML='<span>'+(b===''?'كل الأماكن':pl2(+b))+'</span>'+ch;promoR()}
function promoR(){if($('promo').children.length)return;const P=[['linear-gradient(135deg,#C2410C,#9A3412)','وفّر 10% باشتراك أسبوعي','احجز مرة وامشي 5 أيام','tab(1)'],['linear-gradient(135deg,#2563EB,#1E3A8A)','ادعي صاحبك','شاركه اللينك وخليه يجرب','tab(5)'],['linear-gradient(135deg,#7C3AED,#4C1D95)','كون سواق موثّق','وثّق حسابك وخد شارة وحجوزات أكتر','tab(2)'],['linear-gradient(135deg,#0F766E,#0B4F4A)','مش لاقي مشوار؟','اطلب مشوارك والسواقين هيشوفوه','rqf()']];$('promo').innerHTML=P.map(x=>`<button class="pc" style="background:${x[0]}" onclick="${x[3]}"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}
function pkr(k){bk=null;$('bk').innerHTML=`<div class="card" style="max-height:88vh"><div class="row"><b>${k===1?'هتركب منين؟':'رايح فين؟'}</b><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><input id="pq" aria-label="بحث" placeholder="ابحث عن مكان" oninput="pkl(${k})"><div id="pkl" class="wb"></div></div>`;pkl(k)}
function pkl(k){const q=($('pq').value||'').trim(),L=k===1?PTS:DROP,cur=$(k===1?'f':'df').value,rc=(S.rc||[]).filter(x=>x.k===k),row=(i,t,sub)=>`<button class="pp2" aria-pressed="${String(i)===cur}" onclick="pks(${k},'${i}')"><span><b>${t}</b>${sub?`<br><span class="mu">${sub}</span>`:''}</span><span class="tick"></span></button>`;
const A=k===1?(i=>i>=100&&i<226):(i=>i>=29&&i<155),ai=k===1?(i=>i-100):(i=>i-29),nm=k===1?pl1:pl2,ar=k===1?plArea:dlArea;
const PAR=k===1?PAR_P:PAR_D,mp=q?Object.keys(PAR).map(Number).filter(i=>uiPlaceMatch(L[i],q)):[];
let h=(k===1?`<button class="btn g" onclick="cpf('p')">+ مكاني مش موجود؟ ضيفه</button>`:'')+(q?'':row('','الكل'));
if(!q&&rc.length)h+='<span class="mu">آخر اختياراتك</span>'+rc.map(x=>row(x.i,nm(x.i))).join('');
if(mp.length)h+='<span class="mu" style="margin-top:6px">نقاط التجمع</span>'+mp.slice(0,40).map(i=>row(i,L[i],ar(i))).join('');
['القاهرة','الجيزة'].forEach(gv=>{const m=ord().filter(i=>A(i)&&GOV[L[i]]===gv&&uiPlaceMatch(L[i],q));if(m.length)h+=`<span class="mu" style="margin-top:6px">${gv}</span>`+m.map(i=>row(i,L[i],(MPS[ai(i)]||[]).length?MPS[ai(i)].length+' نقاط تجمع':'')).join('')});
const LR=L.map((n,i)=>[n,i]).filter(x=>x[0]&&(k===1?x[1]<100:x[1]<29)),lm=LR.filter(x=>uiPlaceMatch(x[0],q));
if(lm.length)h+='<span class="mu" style="margin-top:6px">نقاط مشهورة في الجيزة</span>'+lm.map(x=>row(x[1],x[0],ar(x[1]))).join('');
$('pkl').innerHTML=h||'<span class="mu">مفيش نتايج.</span>'}
function pkm(k,a){bk=null;const L=k===1?PTS:DROP,base=k===1?1000:3000,aid=k===1?100+a:29+a,cur=$(k===1?'f':'df').value,PAR=k===1?PAR_P:PAR_D;
const row=(i,t,sub)=>`<button class="pp2" aria-pressed="${String(i)===cur}" onclick="pks(${k},'${i}',1)"><span><b>${t}</b>${sub?`<br><span class="mu">${sub}</span>`:''}</span><span class="tick"></span></button>`;
const pts=(MPS[a]||[]).map((p,j)=>base+a*10+j),leg=Object.keys(PAR).map(Number).filter(i=>i<1000&&PAR[i]===aid);
$('bk').innerHTML=`<div class="card" style="max-height:88vh;overflow:auto"><div class="row"><button class="btn g" style="min-height:36px" onclick="pkr(${k})">رجوع</button><b>${k===1?'هتركب منين في':'رايح فين في'} ${L[aid]}؟</b><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><span class="mu">اختار نقطة التجمع الأقرب ليك، والكابتن بيعدّي عليها في طريقه.</span><div class="wb">${row(aid,'أي نقطة في '+L[aid],'الكابتن يحدد أقرب نقطة على طريقه')}${pts.map(i=>row(i,L[i])).join('')}${leg.map(i=>row(i,L[i])).join('')}</div></div>`}
function pks(k,i,skip){const n=i===''?'':+i,el=$(k===1?'f':'df');if(n!==''&&!el.querySelector('option[value="'+n+'"]')){const o=document.createElement('option');o.value=n;o.textContent=(k===1?PTS:DROP)[n];el.appendChild(o)}el.value=n;if(n!==''){S.rc=[{k,i:n},...(S.rc||[]).filter(x=>!(x.k===k&&x.i===n))].slice(0,6)}save();closeBk();skl();if(skip!==1&&n!==''){const isA=k===1?(n>=100&&n<226):(n>=29&&n<155);if(isA){const a=k===1?n-100:n-29;if((MPS[a]||[]).length)return pkm(k,a)}}}
function selr(){const cur=$('f').value,ch=new Set([...document.querySelectorAll('.pp:checked')].map(e=>+e.value));$('f').innerHTML='<option value="">كل النقاط</option>'+pgOpts();$('f').value=cur;const lb=i=>`<label><input class="pp" type="checkbox" value="${i}" onchange="ttRender()" ${ch.has(i)?'checked':''}>${PTS[i]}${i>12&&i<100?' ★':''}</label>`;
const areaBlk=a=>{const aid=100+a,pts=(MPS[a]||[]).map((p,j)=>1000+a*10+j),leg=Object.keys(PAR_P).map(Number).filter(i=>i<1000&&PAR_P[i]===aid),open=[aid,...pts,...leg].some(i=>ch.has(i));return `<details class="ad"${open?' open':''}><summary>${PTS[aid]}</summary><div class="pts"><label><input class="pp" type="checkbox" value="${aid}" onchange="ttRender()" ${ch.has(aid)?'checked':''}><b>${PTS[aid]} (كل المنطقة)</b></label>${pts.map(lb).join('')}${leg.map(lb).join('')}</div></details>`};
const cust=ord().filter(i=>i>12&&i<100);
$('pp').innerHTML='<span class="mu" style="flex-basis:100%">حدد نقط التجمع اللي بتعدّي عليها في طريقك، والركاب بيركبوا من أقرب نقطة ليهم.</span>'+PGRP.map(g=>{const L=ord().filter(i=>i>=g[1]&&i<g[2]),open=L.some(i=>ch.has(i)||Object.keys(PAR_P).some(x=>PAR_P[x]===i&&ch.has(+x)));return `<details class="ad"${open?' open':''}><summary>${g[0]}</summary>${L.map(i=>areaBlk(i-100)).join('')}</details>`}).join('')+(cust.length?`<details class="ad"${cust.some(i=>ch.has(i))?' open':''}><summary>نقاط مضافة على الطريق</summary><div class="pts">${cust.map(lb).join('')}</div></details>`:'');ttRender()}
function cpf(ctx){bk=null;$('bk').innerHTML=`<div class="card" style="max-height:88vh;overflow:auto"><div class="row"><b>ضيف مكان تاني</b><button class="btn g" style="min-height:36px" onclick="closeBk()">إغلاق</button></div><span class="mu">لو مكانك مش في القايمة، حدده بالنسبة لأقرب نقطة على الطريق. النقطة هتظهر لكل المستخدمين.</span><label for="cpn">اسم المكان</label><input id="cpn" placeholder="مثلاً: أمام مستشفى الهرم"><label for="cpa">بعد أنهي نقطة؟</label><select id="cpa">${ord().filter(i=>i<100).map(i=>`<option value="${i}">${PTS[i]}</option>`).join('')}</select><label for="cpm">بعدها بكام دقيقة؟</label><input id="cpm" type="number" min="1" max="10" value="2"><span class="er" id="cpe" role="alert"></span><button class="btn" onclick="cps('${ctx}')">إضافة</button></div>`}
async function cps(ctx){const n=$('cpn').value.trim(),a=+$('cpa').value,m=+$('cpm').value||0,e=$('cpe');if(!n)return e.textContent='اكتب اسم المكان.';if(PTS.includes(n))return e.textContent='المكان ده موجود بالفعل.';
const nx=ord().find(i=>(OFF[i]||0)>(OFF[a]||0)),gap=nx===undefined?10:(OFF[nx]||0)-(OFF[a]||0);if(gap<2)return e.textContent='مفيش مسافة كافية بعد '+PTS[a]+'. اختار نقطة تانية.';if(m<1||m>=gap)return e.textContent='لازم يكون بين 1 و'+(gap-1)+' دقيقة بعد '+PTS[a]+'.';
const{data,error}=await sb.from('custom_points').insert({name:n,off_minutes:(OFF[a]||0)+m,km:+(((KM[a]||0)+m*14/60).toFixed(1))}).select().single();
if(error)return e.textContent='حصلت مشكلة: '+error.message;
PTS[data.id]=n;OFF[data.id]=data.off_minutes;KM[data.id]=+data.km;selr();closeBk();
if(ctx==='d'){const x=document.querySelector('.pp[value="'+data.id+'"]');if(x){x.checked=true;ttRender()}}else pks(1,String(data.id));toast('اتضافت: '+n+'.')}
function nxr(){const h=new Date().getHours(),b=S.trip||MYBOOKS.find(x=>['accepted','onboard','pending'].includes(x.st));$('gr').textContent=h<12?'صباح الخير':h<18?'مساء الخير':'مساء النور';$('nx').innerHTML=b?`<div class="nx"><div><b>رحلتك الجاية</b><div class="mu">${PTS[b.p]} ${b.t} ← ${DROP[b.dr||0]}${b.wk?' · اشتراك أسبوعي':''}</div></div><button class="btn" onclick="${S.trip?'tab(3)':`trk(${b.rid});`}">تابع</button></div>`:''}

// ---------- auth screens ----------
const EML=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function auErr(m){m=String(m||'');if(/invalid login/i.test(m))return 'الإيميل أو كلمة السر غلط.';if(/already been registered|already registered/i.test(m))return 'الإيميل ده مسجل قبل كده، جرب تسجل دخولك بدل ما تعمل حساب.';if(/at least 6/i.test(m))return 'كلمة السر لازم تكون 6 حروف على الأقل.';if(/valid email|unable to validate/i.test(m))return 'اكتب إيميل صحيح.';if(/rate limit|too many|security purposes/i.test(m))return 'محاولات كتير، استنى دقيقة وجرب تاني.';return 'حصلت مشكلة: '+m}
function auShow(mode){AU_MODE=mode;const e=$('au');e.hidden=false;const inn=mode==='in';
e.innerHTML=`<div class="bh"><div class="bl"><svg viewBox="0 0 48 48" width="34" fill="none" stroke="#fff" stroke-width="4.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 34V19c0-5 7-5 8.8-1l2 5.6c.9 2.4 3.5 2.4 4.4 0l2-5.6c1.8-4 8.8-4 8.8 1v15"/><circle cx="12" cy="34" r="4.6" fill="#fff" stroke="none"/><circle cx="38" cy="34" r="5.2" fill="#A9F2D2" stroke="none"/><circle cx="38" cy="34" r="1.9" fill="#0B4F4A" stroke="none"/></svg></div><b>مشوار معايا</b><small>شارك مشوارك في القاهرة والجيزة، ووفّر</small><div class="tr"><span>سواقين موثّقين</span><span>أرخص بالنص</span><span>نقط تجمع ثابتة</span></div></div><p class="mu" style="max-width:300px;margin:6px 0 0">${inn?'سجل دخولك بالإيميل عشان حسابك يفضل محفوظ على أي جهاز.':'اعمل حساب جديد بالإيميل وكلمة سر. حسابك هيفضل معاك حتى لو مسحت بيانات المتصفح.'}</p><label for="aue">الإيميل</label><input id="aue" type="email" inputmode="email" dir="ltr" placeholder="name@example.com" autocomplete="email"><label for="aup">كلمة السر</label><input id="aup" type="password" dir="ltr" placeholder="٦ حروف على الأقل" autocomplete="${inn?'current-password':'new-password'}"><span class="er" id="aerr" role="alert"></span><button class="btn" style="width:100%;max-width:320px" onclick="auGo()">${inn?'دخول':'إنشاء الحساب'}</button><button class="btn g" style="border:0" onclick="auShow('${inn?'up':'in'}')">${inn?'معندكش حساب؟ اعمل حساب':'عندك حساب؟ سجل دخولك'}</button>${inn?'<button class="btn g" style="border:0" onclick="auReset()">نسيت كلمة السر؟</button>':''}<button class="btn g" style="border:0" onclick="auGuest()">كمّل كضيف من غير حساب</button>`}
async function auGo(){const em=$('aue').value.trim(),pw=$('aup').value,e=$('aerr');if(!EML.test(em))return e.textContent='اكتب إيميل صحيح.';if(pw.length<6)return e.textContent='كلمة السر لازم تكون 6 حروف على الأقل.';e.textContent='ثانية...';
const r=AU_MODE==='in'?await sb.auth.signInWithPassword({email:em,password:pw}):await sb.auth.signUp({email:em,password:pw});
if(r.error)return e.textContent=auErr(r.error.message);
if(AU_MODE==='up'&&!r.data.session)return e.textContent='الحساب اتعمل. افتح إيميلك وأكده لو وصلك لينك، وبعدين سجل دخولك.';
auDone()}
async function auGuest(){const{error}=await sb.auth.signInAnonymously();if(error)return $('aerr').textContent=auErr(error.message);auDone()}
async function auReset(){const em=$('aue').value.trim(),e=$('aerr');if(!EML.test(em))return e.textContent='اكتب إيميلك فوق الأول وبعدين دوس هنا.';const{error}=await sb.auth.resetPasswordForEmail(em,{redirectTo:location.origin+location.pathname});if(error)return e.textContent=auErr(error.message);e.textContent='';toast('بعتنا لينك على إيميلك تعيد منه تعيين كلمة السر.')}
async function auNewPw(){const pw=$('aup').value,e=$('aerr');if(pw.length<6)return e.textContent='كلمة السر لازم تكون 6 حروف على الأقل.';const{error}=await sb.auth.updateUser({password:pw});if(error)return e.textContent=auErr(error.message);$('au').hidden=true;toast('كلمة السر اتغيرت.')}
