function obStart(){if(S.ob)return;oi=0;obr();$('ob').hidden=false}
const OBI=['<path d="M12 2v20M17 6.5c0-2-2.2-3.5-5-3.5s-5 1.5-5 3.5 2.2 3.2 5 3.8 5 1.8 5 3.8-2.2 3.4-5 3.4-5-1.4-5-3.4"/>','<path d="M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.800 12 21 12 21z"/><circle cx="12" cy="9.500" r="2.600"/>','<path d="M12 3l8 3v6c0 4.500-3.400 8-8 9-4.600-1-8-4.500-8-9V6z"/><path d="M8.500 12l2.500 2.500 4.500-5"/>'];
function obr(){const s=OBS[oi];$('ob').innerHTML=`<div class="obi"><svg viewBox="0 0 24 24" aria-hidden="true">${OBI[oi]}</svg></div><h1 style="margin-top:8px">${s[0]}</h1><p class="mu" style="max-width:300px">${s[1]}</p><div class="dots">${OBS.map((_,i)=>`<span class="${i===oi?'on':''}"></span>`).join('')}</div><button class="btn" style="width:100%;max-width:320px" onclick="obn()">${oi===OBS.length-1?'يلا نبدأ':'التالي'}</button><button class="btn g" style="border:0" onclick="obz()">تخطي</button>`}
function obn(){if(oi<OBS.length-1){oi++;obr()}else obz()}
function obz(){$('ob').hidden=true;S.ob=1;save()}
async function reset(){try{await sb.auth.signOut()}catch(e){}localStorage.removeItem(K);location.reload()}
async function poll(){try{await refreshAll(true);await refreshVerification(true);if(!$('v1').hidden||!$('v2').hidden)render();if(S.trip)renderTrip();if(chatBid)loadChat(chatBid).then(()=>{const sh=$('tsh');if(sh)sh.dataset.sig='';renderTrip()})}catch(e){}}
(async function boot(){
  await loadPoints();
  map();selr();
  $('rt').innerHTML=R.map((r,i)=>`<option value="${i}">${r.n}</option>`).join('');
  $('dr').innerHTML=og();$('df').innerHTML='<option value="">كل الأماكن</option>'+og();
  ttRender();cm();
  const{data:{session}}=await sb.auth.getSession();
  if(!session)await new Promise(r=>{AU_RES=r;auShow('in')});
  const{data:{user}}=await sb.auth.getUser();
  ME=user&&user.id;ME_ANON=!!(user&&user.is_anonymous);ME_EMAIL=(user&&user.email)||'';
  if(ME){await loadProfile();await refreshAll(false);await refreshStats();
  try{const{data:ia}=await sb.rpc('is_admin');IS_ADMIN=!!ia;if(IS_ADMIN)$('n6').hidden=false}catch(e){}}
  render();tab(1);
  setTimeout(()=>{$('sp').style.opacity=0;setTimeout(()=>$('sp').remove(),500)},1200);
  setTimeout(obStart,1300);
  setInterval(poll,15000);
  setInterval(updMap,250);
  try{sb.channel('live').on('postgres_changes',{event:'*',schema:'public',table:'bookings'},()=>poll()).on('postgres_changes',{event:'*',schema:'public',table:'rides'},()=>poll()).subscribe()}catch(e){}
})();

